; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: system80 (Dick Smith System 80 / Video Genie (direct video)), starts in normal mode
; ============================================================

			org #5200

; ============================================================
; Platform start code (the platform's ntc_plat_romhead) - at the org, on to ntc_start
; ============================================================
; Entry at ;@org (the /CMD transfer address). Model I / System 80: di is enough -
; there is no E4/E0 to clear (the disk IRQ is maskable, via #37E0).  ;!!S80
ntc_s80_start:
			di
			jp ntc_start

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_trs_stack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 14: Print "1 started"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 15: Wait
			dw p_wait_c

			; 16: Print "2 Capability LOAD"; FileSystem.Capability("LOAD"); " SAVE"; FileSystem.Capability("SAVE")
			dw kw_printstrvar, str3
			dw kw_printnl

			; 17: Wait
			dw p_wait_c

			; 18: Print "3 Devices: "; FileSystem.Devices()
			dw kw_printstrvar, str4
			dw kw_printnl

			; 19: Wait
			dw p_wait_c

			; 20: Print "4 CurrentDevice: "; FileSystem.CurrentDevice(); "  Volume: "; FileSystem.CurrentVolume()
			dw kw_printstrvar, str5
			dw kw_printnl

			; 21: Wait
			dw p_wait_c

			; 22: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; 23: Print "5 Save STEP.DAT..."
			dw kw_printstrvar, str6
			dw kw_printnl

			; 24: Wait
			dw p_wait_c

			; 25: r = FileSystem.Save("STEP.DAT", VarPtr(a), 20)
			dw kw_ztov, var_r

			; 26: Print "  Save gave"; r
			dw kw_printstrvar, str8
			dw kw_printint, var_r
			dw kw_printnl

			; 27: Wait
			dw p_wait_c

			; 28: Print "6 Load STEP.DAT..."
			dw kw_printstrvar, str9
			dw kw_printnl

			; 29: Wait
			dw p_wait_c

			; 30: r = FileSystem.Load("STEP.DAT", VarPtr(b), 20)
			dw kw_ztov, var_r

			; 31: Print "  Load gave"; r; ", "; b(0); " ... "; b(9)
			dw kw_printstrvar, str10
			dw kw_printint, var_r
			dw kw_printstrvar, str11
			dw kw_printint, arr_b
			dw kw_printstrvar, str12
			dw kw_printint, arr_b+18
			dw kw_printnl

			; 32: Print "7 done"
			dw kw_printstrvar, str13
			dw kw_printnl

			; 33: End
			dw kw_printnl0
			dw kw_printstrvar, str14
			dw kw_waitkey_n
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; 36: Print "  (press a key)"
			dw kw_printstrvar, str15
			dw kw_printnl

			; 37: Do While Inkey <> 0 : Loop
do2_t:
			dw kw_inkey_n, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_e
			dw do2_t_go
do2_e:

			; 38: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey_n, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_i:			dw 0
var_r:			dw 0
p_wait_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0

; numbers passed by address (read only)
vp_arr_a:			dw arr_a
vp_arr_b:			dw arr_b

; ============================================================
; Strings
; ============================================================

str0:			db "1 started", 0
str1:			db "LOAD", 0
str2:			db "SAVE", 0
str3:			db "2 Capability LOAD0 SAVE0", 0
str4:			db "3 Devices: 0", 0
str5:			db "4 CurrentDevice: 0  Volume: 0", 0
str6:			db "5 Save STEP.DAT...", 0
str7:			db "STEP.DAT", 0
str8:			db "  Save gave", 0
str9:			db "6 Load STEP.DAT...", 0
str10:			db "  Load gave", 0
str11:			db ", ", 0
str12:			db " ... ", 0
str13:			db "7 done", 0
str14:			db "Press a key to end", 0
str15:			db "  (press a key)", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_ivar @data
ntc_ivar:		dw 0			; inputint / inkey: dest var

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey (normal mode copy) ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey_n:
			ld ix, ntc_xn
			jp ntc_plat_getkey_n

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ex de, hl
			or a
			sbc hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvl ntc_mul
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop de
			jp ntc_mul

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_inkey (normal mode copy) ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey_n:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got_n
			jp ntc_plat_scankey_n
ntc_inkey_got_n:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			jp ntc_xn

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_frame ntc_data
; No clock poll: the Model I heartbeat (#37E0, ~40Hz) differs from the Model
; III's E0/EC and isn't wired. Return at once (no pacing).  ;!!S80
ntc_plat_frame:
			jp (ix)

; ============================================================
; NTC Platform - TRS-80 Model III (Z80, direct video)   *** DRAFT ***
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ============================================================
; STATUS: compiles AND assembles (sjasmplus, Z80). Not yet run on a Model III /
; Model 4 (III mode) or an emulator. Grounded from Julian's "TRS-80 hardware,
; for NTC BASIC" notes (trs-80.com ports/RAM pages, MAME trs80m3.cpp). Points he
; marked (check) there are marked ;!!TRS here.
;
; THE MACHINE (Model III):
;   * Z80 @ 2.03 MHz. One flat block - no 16K window, no RAM pages (like the
;     SC-3000 / ColecoVision, but with much more RAM):
;       #0000-#37FF  ROM (incl. #0066 NMI, #0038 RST38)
;       #3800-#3BFF  keyboard matrix (memory-mapped, read only)
;       #3C00-#3FFF  video RAM, 64 x 16 characters (#00-#7F ASCII)
;       #4000 up     RAM (low RAM holds ROM/DOS vectors); user load ~#5200
;   * SP is the thread, so ANY interrupt or NMI that pushes while SP is the
;     thread wrecks it. Startup therefore: di; E4=0 (no disk NMI); E0=0 (no
;     maskable interrupts). Turbo-only for now, like the ColecoVision (normal-
;     mode clock handling not wired - see Frame).
;   * A push is only safe once SP is swapped to the real stack (ntc_csp). So the
;     console hooks, which write straight to #3C00, use NO call/push (pure memory
;     writes); only the key scan swaps SP (it shares one call/ret scan body).
;
; DISK (future FileSystem) - Julian's safe pattern, kept here as the reference:
;       ld (ntc_ip), sp         ; save the thread
;       ld sp, (ntc_csp)        ; a real stack
;       ld a, #80
;       out (#E4), a            ; NMI on INTRQ: the disk can interrupt now
;       ... the disk command, wait for it ...
;       xor a
;       out (#E4), a            ; NMI off again
;       ld sp, (ntc_ip)         ; back on the thread
;   While the NMI is on, its pushes land on the real stack. Better still, poll
;   the WD1793 busy bit at #F0 and never enable the NMI (only the DOS's own disk
;   routines need it).
; ============================================================
;@org      #5200
;@text     byte
;@scrinit  0
;@irq      0
;@stack    ntc_trs_stack
;@cols     64
;@rows     16
; ============================================================

;## ntc_plat_data ntc_data
VIDEO       equ #3C00               ; video RAM base
VIDCOLS     equ 64
VIDROWS     equ 16
VIDLAST     equ VIDEO + VIDCOLS*(VIDROWS-1)   ; #3FC0, start of the bottom row
INTMASK     equ #E0                 ; maskable interrupt mask (write) / status (read)
INTCLR      equ #EC                 ; read clears the 30Hz clock interrupt
NMIMASK     equ #E4                 ; NMI mask: bit7 INTRQ, bit6 DRQ; 0 = off  ;!!TRS
DOSRET      equ #402D               ; DOS return entry (TRSDOS 1.3 III; TRSDOS 2.3 / NEWDOS I) ;!!TRS

ntc_curx:   db 0                    ; column (0..63), counted for Tab
ntc_cury:   db 0                    ; row (0..15)
ntc_scols:  db 64
ntc_frames: dw 0                    ; frames counted by ntc_plat_frame (ntc_plat_ticks)
ntc_trs_stack equ ntc_end + 256     ; the real stack: the 256 bytes above the program image

;## ntc_plat_screen ntc_plat_data ntc_data
; routines here are entered via jp with IX = where to go next; they end jp (ix).
; No real stack: direct memory writes only, so no call / no push on the thread.

; ntc_plat_putc - A = character; write it at the cursor, advance (wrap -> newline)
ntc_plat_putc:
			ld c, a                     ; keep the char
			; HL = VIDEO + cury*64 + curx  (inline, no call)
			ld a, (ntc_cury)
			ld h, 0
			ld l, a
			add hl, hl                  ; *2
			add hl, hl                  ; *4
			add hl, hl                  ; *8
			add hl, hl                  ; *16
			add hl, hl                  ; *32
			add hl, hl                  ; *64
			ld a, (ntc_curx)
			ld e, a
			ld d, 0
			add hl, de
			ld de, VIDEO
			add hl, de
			ld (hl), c                  ; draw the character
			ld a, (ntc_curx)
			inc a
			cp VIDCOLS
			jr c, ntc_pc_col
			jp ntc_plat_newline         ; past column 63 -> newline
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - column 0, next row; scroll when past the bottom row
ntc_plat_newline:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp VIDROWS
			jr c, ntc_nl_row
			; scroll rows 1..15 up to 0..14, blank the bottom row (ldir, no push)
			ld hl, VIDEO + VIDCOLS
			ld de, VIDEO
			ld bc, VIDCOLS*(VIDROWS-1)  ; 960
			ldir
			ld hl, VIDLAST
			ld (hl), ' '
			ld de, VIDLAST + 1
			ld bc, VIDCOLS - 1
			ldir
			ld a, VIDROWS-1
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_key (normal mode copy) ntc_plat_data ntc_data
; ntc_plat_scankey - A = ASCII of a held key, 0 if none.  ntc_plat_getkey - wait.
; Both swap SP to the real stack so the one scan body (ntc_trs_scan, call/ret)
; can be called safely, then swap back. ntc_trs_scan reads the matrix rows
; directly (#3800+2^row). Core subset: A-Z, 0-9, ENTER (13), SPACE (32).
; ;!!TRS SHIFT (#3880 bit0/bit1), the symbol keys (#3820 bits 2-7) and the CPC-
; style key numbers the Keys class wants are not mapped yet.
ntc_plat_scankey_n:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			call ntc_trs_scan_n
			ld sp, (ntc_ip)
			jp (ix)
ntc_plat_getkey_n:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
ntc_gk_wait_n:
			call ntc_trs_scan_n
			or a
			jr z, ntc_gk_wait_n
			ld sp, (ntc_ip)
			jp (ix)

; ntc_trs_scan - A = ASCII of a held key, 0 if none (call/ret, real stack)
ntc_trs_scan_n:
			ld hl, ntc_trs_ktab_n
ntc_sc_row_n:
			ld e, (hl)
			inc hl
			ld d, (hl)                  ; DE = row address (0 ends the table)
			inc hl
			ld a, d
			or e
			jr z, ntc_sc_r6_n             ; table end -> ENTER / SPACE row
			ld c, (hl)                  ; C = base char (bit 0)
			inc hl
			ld b, (hl)                  ; B = allowed-bit mask
			inc hl
			ld a, (de)
			and b
			jr z, ntc_sc_row_n            ; nothing held in this row
			ld b, c                     ; B = base char; find the lowest set bit
ntc_sc_bit_n:
			rra
			jr c, ntc_sc_hit_n
			inc b
			jr ntc_sc_bit_n
ntc_sc_hit_n:
			ld a, b
			jp ntc_xn
ntc_sc_r6_n:
			ld a, (#3840)               ; ENTER CLEAR BREAK arrows SPACE
			bit 0, a
			jr z, ntc_sc_sp_n
			ld a, 13                    ; ENTER
			jp ntc_xn
ntc_sc_sp_n:
			ld a, (#3840)
			bit 7, a
			jr z, ntc_sc_none_n
			ld a, 32                    ; SPACE
			jp ntc_xn
ntc_sc_none_n:
			xor a
			jp ntc_xn

; row-address / base-char / allowed-mask table (bit 0 = base char, bit n = base+n)
ntc_trs_ktab_n:
			dw #3801
			db '@', #FF                 ; @ A B C D E F G
			dw #3802
			db 'H', #FF                 ; H I J K L M N O
			dw #3804
			db 'P', #FF                 ; P Q R S T U V W
			dw #3808
			db 'X', #07                 ; X Y Z
			dw #3810
			db '0', #FF                 ; 0 1 2 3 4 5 6 7
			dw #3820
			db '8', #03                 ; 8 9 (bits 2-7 are : ; , - . /  ;!!TRS)
			dw 0

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - End: hand back to the DOS at its return entry (#402D).
ntc_plat_exit:
			jp DOSRET

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = first byte the Memory heap must not use (grows down from
; here). ;!!TRS #F000 is conservative; the DOS's MEMEND (TRSDOS 1.3 #4411) is the
; real ceiling - read it once the DOS is known.
ntc_plat_memtop:
			ld hl, #F000
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_a		equ ntc_bss + 0		; 20 bytes
arr_b		equ ntc_bss + 20		; 20 bytes
ntc_bss_size	equ 40
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
